export const GYEONGGI_REGIONS = Object.freeze(geometries.filter(item => item.level === 'city'));
export const GYEONGGI_DISTRICTS = Object.freeze(geometries.filter(item => item.level === 'district'));

export function projectPoint(lon, lat) {
  if (!Number.isFinite(lon) || !Number.isFinite(lat) || Math.abs(lon) > 180 || Math.abs(lat) > 90) throw new TypeError('Expected WGS84 longitude and latitude');
  return {x: PROJECTION.offsetX + (lon * PROJECTION.cosLatitude - PROJECTION.projectedBounds.minX) * PROJECTION.scale,
    y: PROJECTION.offsetY + (-lat - PROJECTION.projectedBounds.minY) * PROJECTION.scale};
}
